// 1. Obtém o texto do CSV que veio do HTTP Request
const csvTexto = $input.first().json.data;
// 2. Divide o texto em linhas e descarta linhas vazias
const linhas = csvTexto
  .trim()
  .split('\n')
  .map(linha => linha.trim())
  .filter(linha => linha.length > 0);
// 3. Monta a lista com cada um dos investimentos
const listaInvestimentos = [];
for (let i = 1; i < linhas.length; i++) {
  const colunas = linhas[i].split(',').map(c => c.trim());

  if (colunas.length >= 4) {
    listaInvestimentos.push({
      perfil: colunas[0],
      produto: colunas[1],
      minimo: Number(colunas[2]), // Normaliza para número
      rentabilidade: colunas[3]
    });
  }
}
// 4. Retorna como um único item com a lista "investimentos"
return [
  {
    json: {
      investimentos: listaInvestimentos
    }
  }
];

// 1. Obtém os dados dos clientes do Webhook e os investimentos do nó anterior
const dadosWebhook = $('Webhook').first().json;
const clientes = dadosWebhook.body?.clientes || dadosWebhook.clientes || [];

const investimentos = $input.first().json.investimentos || $('Code in JavaScript').first().json.investimentos || [];

// 2. Frases humanizadas de contexto por produto
const detalhesHumanizados = {
  "Poupança": {
    titulo: "Poupança: Ideal para reserva de emergência com total facilidade.",
    vantagem: "Perfeita para quem busca simplicidade imediata e risco praticamente zero."
  },
  "CDB Liquidez Diária": {
    titulo: "CDB Liquidez Diária: Excelente equilíbrio entre rentabilidade e resgate a qualquer momento.",
    vantagem: "Permite resgatar quando quiser com garantia do FGC e rendimento superior à poupança."
  },
  "Tesouro Selic": {
    titulo: "Tesouro Selic: O título público federal mais seguro do mercado.",
    vantagem: "Ótima escolha para valorizar seu capital acompanhando a taxa básica de juros."
  },
  "CDB Prefixado": {
    titulo: "CDB Prefixado: Garanta uma taxa de rentabilidade fixa e previsível.",
    vantagem: "Ideal para saber exatamente quanto vai receber no vencimento, sem surpresas."
  },
  "Fundo Multimercado": {
    titulo: "Fundo Multimercado: Gestão profissional com diversificação em vários ativos.",
    vantagem: "Combina estratégias inteligentes para buscar ganhos consistentes acima da inflação."
  },
  "Tesouro IPCA+": {
    titulo: "Tesouro IPCA+: Proteção real contra a inflação com juros garantidos.",
    vantagem: "Preserva o seu poder de compra no futuro e entrega rentabilidade real contratada."
  },
  "Ações ETF": {
    titulo: "Ações ETF: Exposição diversificada às maiores empresas da bolsa de valores.",
    vantagem: "Permite participar do crescimento corporativo com praticidade e baixo custo."
  },
  "Fundo de Ações": {
    titulo: "Fundo de Ações: Carteira gerida por especialistas focada em valorização.",
    vantagem: "Excelente veículo para maximizar retornos de longo prazo com gestão ativa."
  },
  "Criptomoedas": {
    titulo: "Criptomoedas: Ativos digitais globais com alto potencial de valorização.",
    vantagem: "Para quem busca inovação e diversificação com estratégia em tecnologia descentralizada."
  }
};

// 3. Processa cada cliente
const resultado = clientes.map(cliente => {
  // Filtra as 3 opções do perfil do investidor
  const opcoes = investimentos.filter(
    inv => inv.perfil && inv.perfil.toLowerCase() === String(cliente.perfil).toLowerCase()
  ).slice(0, 3);

  // Monta as 3 mensagens curtas em lista enumerada (máx. 3 linhas cada)
  const listaMensagens = opcoes.map((op, idx) => {
    const minimoFormatado = Number(op.minimo).toLocaleString('pt-BR', { minimumFractionDigits: 2 });
    const info = detalhesHumanizados[op.produto] || {
      titulo: `${op.produto}: Opção consistente para seu perfil.`,
      vantagem: "Alternativa eficiente para rentabilizar seus recursos disponíveis."
    };

    return [
      `${idx + 1}. ${info.titulo}`,
      `   • Aplicação mínima: R$ ${minimoFormatado} | Rentabilidade: ${op.rentabilidade}`,
      `   • ${info.vantagem}`
    ].join('\n');
  });

  // Identifica a opção mais recomendada (índice 1 como padrão ou primeira opção que cabe no saldo)
  const indiceRecomendado = (cliente.perfil.toLowerCase() === "conservador") ? 1 : 0;
  const mensagemOpcaoRecomendada = listaMensagens[indiceRecomendado] || listaMensagens[0];

  // Junta as 3 mensagens pulando uma linha entre elas
  const textoTresOpcoes = listaMensagens.join("\n\n");

  // Monta a mensagem completa final
  const mensagemCompleta = `Olá, ${cliente.nome}! 

Analisamos o seu perfil ${cliente.perfil} e o seu saldo de ${cliente.saldo}. Selecionamos 3 alternativas sob medida para você:

${textoTresOpcoes}

--------------------------------------------------
⭐ Opção Recomendada para o seu Momento:
${mensagemOpcaoRecomendada}

Estamos à disposição para tirar qualquer dúvida e apoiar suas decisões financeiras!`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo: cliente.saldo,
      mensagem: mensagemCompleta
    }
  };
});

return resultado;

// 1. Obtém os dados dos clientes do Webhook e os investimentos do nó anterior
const dadosWebhook = $('Webhook').first().json;
const clientes = dadosWebhook.body?.clientes || dadosWebhook.clientes || [];

const investimentos = $input.first().json.investimentos || $('Code in JavaScript').first().json.investimentos || [];

// 2. Processa cada cliente organizando cada dado em sua respectiva coluna
const resultado = clientes.map(cliente => {
  // Converte "R$ 12.500,00" para número puro: 12500
  const saldoNumero = Number(
    String(cliente.saldo || "0")
      .replace('R$', '')
      .replace(/\./g, '')
      .replace(',', '.')
      .trim()
  ) || 0;

  // Filtra os investimentos compatíveis com o perfil do cliente
  const opcoesPerfil = investimentos.filter(
    inv => inv.perfil && inv.perfil.toLowerCase() === String(cliente.perfil).toLowerCase()
  );

  // Seleciona a melhor opção para o perfil
  let rec = opcoesPerfil.find(op => op.minimo <= saldoNumero && op.produto !== "Poupança") || opcoesPerfil[0] || {
    perfil: cliente.perfil,
    produto: "CDB Liquidez Diária",
    minimo: 1000,
    rentabilidade: "12.5%"
  };

  if (String(cliente.perfil).toLowerCase() === "arrojado") {
    rec = opcoesPerfil.find(op => op.produto.includes("Fundo") || op.produto.includes("ETF")) || rec;
  }

  // Verifica se o saldo do cliente é suficiente para o investimento
  const saldoEstaOk = saldoNumero >= rec.minimo;
  const statusSaldo = saldoEstaOk ? "saldo_ok" : "saldo_insuficiente";

  // Formata o valor mínimo para uso dentro do texto da mensagem
  const minimoFormatado = Number(rec.minimo).toLocaleString('pt-BR', { minimumFractionDigits: 2 });

  // Cria a mensagem de recomendação
  const mensagemRecomendacao = saldoEstaOk
    ? `Olá ${cliente.nome}! Para o seu perfil ${cliente.perfil}, indicamos o ${rec.produto} (Mínimo: R$ ${minimoFormatado} | Rentabilidade: ${rec.rentabilidade}). Seu saldo atual de ${cliente.saldo} é suficiente para realizar esta aplicação com segurança.`
    : `Olá ${cliente.nome}! Para o seu perfil ${cliente.perfil}, indicamos o ${rec.produto} (Mínimo: R$ ${minimoFormatado}). Seu saldo atual (${cliente.saldo}) ainda é inferior ao valor mínimo necessário.`;

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo_original: cliente.saldo,
      saldo_numero: saldoNumero,
      investimento_indicado: {
        perfil: rec.perfil,
        produto: rec.produto,
        minimo: Number(rec.minimo),
        rentabilidade: rec.rentabilidade
      },
      status_saldo: statusSaldo,
      mensagem_recomendacao: mensagemRecomendacao
    }
  };
});

return resultado;

// Modo: Run Once for All Items
const itensIa = $input.all();

return itensIa.map((item, index) => {
  // 1. Vincula com segurança aos dados originais do cliente no 'Code in JavaScript2'
  let dadosCliente = {};
  try {
    dadosCliente = $('Code in JavaScript2').itemMatching(index).json || {};
  } catch (e) {
    dadosCliente = item.json || {};
  }

  // 2. Garante o e-mail de destino (evita a coluna 'to' ficar vazia/empty)
  const destinatarioEmail = (dadosCliente.email || item.json.email || dadosCliente.to || '').trim();

  // 3. Localiza e extrai o texto retornado pelo modelo de IA
  let textoBruto = '';
  if (item.json.output?.[0]?.content?.[0]?.text) {
    textoBruto = item.json.output[0].content[0].text;
  } else if (item.json.content?.[0]?.text) {
    textoBruto = item.json.content[0].text;
  } else if (typeof item.json.content === 'string') {
    textoBruto = item.json.content;
  } else {
    textoBruto = item.json.text || '';
  }

  // [PROTEÇÃO EXTRA]: Remove qualquer caractere estranho (!, ?, espaços) antes de "Assunto:"
  textoBruto = textoBruto.replace(/^[\s!?,.-]+(?=Assunto:)/i, '').trim();

  // 4. Limpa formatação markdown se houver (```json ... ```)
  let textoLimpo = textoBruto
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  // 5. Tenta interpretar como JSON ou extrai o "Assunto:" do texto puro
  let subject = '';
  let text_body = '';

  try {
    const parsed = JSON.parse(textoLimpo);
    subject = parsed.subject;
    text_body = parsed.text_body;
  } catch (err) {
    // Se a IA respondeu em texto direto iniciando por "Assunto: ..."
    const regexAssunto = /^Assunto:\s*(.+)$/im;
    const matchAssunto = textoBruto.match(regexAssunto);

    if (matchAssunto && matchAssunto[1]) {
      subject = matchAssunto[1].trim();
      // Remove a linha do assunto do corpo para não duplicar no e-mail
      text_body = textoBruto.replace(regexAssunto, '').trim();
    } else {
      subject = `Sugestão de Investimento para ${dadosCliente.nome || 'você'}`;
      text_body = textoBruto;
    }
  }

  // Fallbacks de segurança caso algum campo venha vazio
  if (!subject) {
    subject = `Oportunidade para você, ${dadosCliente.nome || ''}`;
  }
  if (!text_body) {
    text_body = textoBruto;
  }

  // 6. Converte o texto em HTML elegante com parágrafos para o Gmail
  const html_body = text_body
    .split(/\n\s*\n/)
    .filter(paragrafo => paragrafo.trim().length > 0)
    .map(paragrafo => `<p style="margin-bottom: 12px; line-height: 1.5; color: #222;">${paragrafo.replace(/\n/g, '<br>')}</p>`)
    .join('');

  // 7. Retorno padronizado para o nó do Gmail
  return {
    json: {
      ok: Boolean(destinatarioEmail && subject && text_body),
      to: destinatarioEmail,
      subject: subject,
      text_body: text_body,
      html_body: html_body,
      meta: {
        nome: dadosCliente.nome || '',
        perfil: dadosCliente.perfil || '',
        saldo: dadosCliente.saldo_original || dadosCliente.saldo || '',
        investimento: dadosCliente.investimento_indicado?.produto || ''
      }
    }
  };
});
